// A pane moved to be a band across the whole layout (`moveToEdge`, layoutTree.ts) is predicted by the frontend and
// stored by srv (`move_to_edge`, crates/srv-core/src/backend/layout/intent.rs), and the two must agree: this replays
// srv's result for each case, generated by crates/srv-core/src/backend/layout/intent/edge_tests.rs, through the
// frontend's own reducer and balance pass.

import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { applyLayoutAction, intentForAction, sameLayoutTree } from "../lib/layoutIntentActions";
import { balanceNode, withDerivedNodeIds } from "../lib/layoutNode";
import { LayoutEdge, LayoutNode, LayoutTreeActionType, LayoutTreeMoveToEdgeAction, LayoutTreeState } from "../lib/types";

type Case = { name: string; initial: LayoutNode; nodeId: string; edge: LayoutEdge; actionId: string; applied: boolean; final: LayoutNode };

const file = JSON.parse(readFileSync(new URL("./fixtures/layout-edge-vectors.json", import.meta.url), "utf8"));
const cases: Case[] = file.cases;
const copy = <T>(v: T): T => JSON.parse(JSON.stringify(v));

/** One step as `LayoutModel.treeReducer` + `updateTree` run it. */
function step(state: LayoutTreeState, c: Case): void {
    const action: LayoutTreeMoveToEdgeAction = { type: LayoutTreeActionType.MoveToEdge, nodeId: c.nodeId, edge: c.edge };
    const before = copy(state.rootNode);
    try {
        withDerivedNodeIds(c.actionId, () => applyLayoutAction(state, action));
        if (state.rootNode) state.rootNode = balanceNode(state.rootNode);
    } catch {
        // The frontend's reducer throws where srv refuses; the tree it had stays.
        state.rootNode = before;
    }
}

describe("a pane moved to the layout's edge (srv's results, replayed by the frontend's reducer)", () => {
    it("covers every layout, every pane and every edge", () => {
        expect(cases.length).toBeGreaterThan(60);
        expect(new Set(cases.map((c) => c.edge))).toEqual(new Set(["top", "bottom", "middle"]));
        expect(cases.some((c) => c.applied)).toBe(true);
        expect(cases.some((c) => !c.applied)).toBe(true);
    });

    for (const [i, c] of cases.entries()) {
        it(`${c.name}: ${c.nodeId} to the ${c.edge} (case ${i})`, () => {
            const state: LayoutTreeState = { rootNode: copy(c.initial), pendingBackendActions: [] };
            step(state, c);
            // Refused by srv: the frontend must not have changed anything either.
            expect(sameLayoutTree(state.rootNode, c.final), `${c.name}: ${c.nodeId} to the ${c.edge}`).toBe(true);
        });
    }

    it("is an intent srv applies, under the name srv knows it by", () => {
        const action: LayoutTreeMoveToEdgeAction = { type: LayoutTreeActionType.MoveToEdge, nodeId: "a", edge: "bottom" };
        expect(intentForAction(action)).toEqual({ type: "movetoedge", nodeId: "a", edge: "bottom" });
    });
});
